#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const PACKAGE = 'data/fag/litteratur/litteraturvitenskap_canonical_v1';
const read = (file) => JSON.parse(fs.readFileSync(path.join(ROOT, file), 'utf8'));
const write = (file, value) => {
  const target = path.join(ROOT, file);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, `${JSON.stringify(value, null, 2)}\n`);
};
const words = (value) => String(value).trim().split(/\s+/u).filter(Boolean).length;
const concept = (id, term, focus, boundary) => ({
  id,
  term,
  definition: `${term} betegner ${focus}. Begrepet må anvendes på lokaliserbare tekststeder, medier, handlinger, institusjoner eller historiske spor.`,
  distinguish_from: `Må skilles fra ${boundary}, som krever en annen analyseenhet eller evidenstype.`
});
const completionEvidence = [
  'særskrevet hovedartikkel med alle underkrav',
  'definerte begreper med eksplisitte grensedragninger',
  'fullt arbeidseksempel og minst to sammenligningsobjekter',
  'kildeførte historiske og geografiske utsagn',
  'anvendelse av minst to teoritradisjoner og to metoder',
  'eksplisitt avgrensning mot canonicale naboområder'
];
const completionRules = [
  'Alle seks temakrav skal være oppfylt.',
  'Hvert underdekningspunkt skal ha avsnittsevidens.',
  'Alle obligatoriske begreper skal være definerte og avgrensede.',
  'Hvert tema skal anvende minst tre navngitte analyseobjekter.',
  'Minst to teoritradisjoner og to metoder skal anvendes per tema.',
  'Historisk og geografisk dekning skal være kildeført.',
  'Tekst, utgave, medium, målgruppe og institusjon skal identifiseres før generalisering.',
  'Dokumentert spor skal skilles fra antatt intensjon, epokekarakter og virkning.',
  'Alders-, språk-, tilgangs-, representasjons- og rettighetsgrenser skal stå eksplisitt.',
  'Permanent audit skal validere fulfillment-filen.'
];
const evidenceFields = ['topicId', 'sectionIds', 'conceptIds', 'claimIds', 'sourceIds', 'appliedTheoryTraditions', 'appliedMethods', 'namedAnalysisObjects', 'historicalCoverage', 'geographicalCoverage', 'boundaryAreaIds', 'subcoverageEvidence', 'theoryEvidence', 'methodEvidence', 'namedObjectEvidence'];
const paragraphFrames = [
  (spec, item, object, theory, method, history, geography, bounds) => `Artikkelen avgrenser ${item} som et selvstendig problem i ${spec.title.toLowerCase()}. ${object} undersøkes med ${method} og ${theory}; analysen må vise hvilket tekststed, oppslag, vers, scene, dokument eller lesespor som bærer tolkningen. Materialet plasseres i ${history} og ${geography}, men periode og sted fungerer som undersøkte historiske forhold, ikke som ferdige forklaringer. Sammenligning krever samme analyseenhet og synliggjør også avvik i språk, medium, publikum og tilgang. Konklusjonen skiller dokumentert form fra antatt forfatterintensjon og senere virkning. Feltgrensen går mot ${bounds}, som kan utdype saken, men ikke erstatte denne evidensen.`,
  (spec, item, object, theory, method, history, geography, bounds) => `${item} krever at analysen skiller tekstens konstruerte posisjoner fra faktiske lesere, aktører eller historiske grupper. I ${object} brukes ${method} til å prøve en påstand formulert gjennom ${theory}; minst ett rivaliserende svar må vurderes. Undersøkelsen følger materialet fra ${history} til ${geography} uten å gjøre én nasjonal kanon eller moderne kategori universell. Utgave, oversettelse, illustrasjon, framføring, skolebruk og institusjon registreres når de endrer hva som kan observeres. Fravær i en samling eller læreplan er først et dokumentert hull, ikke bevis for historisk ubetydelighet. Avgrensningen mot ${bounds} hindrer at identitet, pedagogikk eller periode blir en totalforklaring.`,
  (spec, item, object, theory, method, history, geography, bounds) => `For ${item} låses analyseenhet og sammenligningsgrunnlag før begrepet anvendes. ${object} gir et konkret arbeidseksempel der ${method} kombineres med ${theory}; påstanden må kunne føres tilbake til ordvalg, komposisjon, bilde, bokobjekt, manuskriptvariant, sirkulasjon eller dokumentert respons. ${history} gir en tidsakse, mens ${geography} gjør språk- og institusjonsforskjeller synlige. En senere standardutgave kan ikke alene representere en tidligere teksttilstand, og en moderne lesning dokumenterer ikke automatisk opprinnelig funksjon. Resultatet oppgir usikkerhet og hvilke nye funn som kunne endre vurderingen. ${bounds} behandles som nabofelt med egne spørsmål og kildekrav.`,
  (spec, item, object, theory, method, history, geography, bounds) => `Analysen av ${item} begynner med hvem som produserer, formidler, leser, framfører eller bevarer materialet. I ${object} gjør ${method} det mulig å anvende ${theory} uten å redusere verket til en illustrasjon av teorien. Sporene må dateres og knyttes til ${history} samt ${geography}; samtidige normer, teknologier og maktforhold må dokumenteres framfor å projiseres bakover. Forskjellen mellom foreskrevet bruk og faktisk praksis holdes åpen, og én kanonisk gjenstand kan ikke stå for en hel epoke eller målgruppe. Analysen angir kilde-, språk-, representasjons- og rettighetsgrense. Den skiller dessuten feltet fra ${bounds}.`,
  (spec, item, object, theory, method, history, geography, bounds) => `${item} undersøkes som en relasjon mellom form, medium og situert bruk. ${object} analyseres gjennom ${method} med ${theory} som eksplisitt perspektiv, men både teoriens gevinst og blindfelt rapporteres. Sammenstillingen mellom ${history} og ${geography} må bevare ulikheter i sjanger, skriftkultur, alder, utdanning, klasse, kjønn, språk og tilgang når disse er relevante. Popularitet, skoleplassering, arkivoverlevelse og estetisk verdi er forskjellige påstander og trenger forskjellige kilder. Arbeidseksemplet viser derfor både hovedtolkning og et moteksempel. Avgrensningen mot ${bounds} sørger for at det lokale spørsmålet kan etterprøves.`,
  (spec, item, object, theory, method, history, geography, bounds) => `Ved ${item} behandles kategoriens egen historie som en del av materialet. ${object} leses med ${method} og ${theory}, men analysen tester om begrepene faktisk passer tekstens språk, medium og samtidige institusjoner. ${history} kobles til ${geography} gjennom dokumenterte utgaver, oversettelser, tidsskrifter, biblioteker, skoler eller digitale plattformer. En kronologisk plassering er ikke i seg selv en forklaring, og likhet mellom verk viser ikke direkte påvirkning uten et sirkulasjonsspor. Påstanden graderes etter hva kildene støtter og hva som forblir hypotese. ${bounds} markeres som nødvendige grenseflater, ikke som synonymer for emnet.`,
  (spec, item, object, theory, method, history, geography, bounds) => `Den avsluttende delen om ${item} gjør analysens begrensninger like synlige som funnene. I ${object} brukes ${method} sammen med ${theory} for å følge ett presist spor fra materialbeskrivelse til fortolkning. Eksemplet kontrolleres mot ${history} og ${geography}, og alternative periodiseringer, målgrupper eller tradisjoner prøves der de kan endre resultatet. Arkivtap, oversettelse, modernisert rettskrivning, pedagogisk tilrettelegging og plattformendring registreres før fravær eller effekt hevdes. Konklusjonen angir evidensnivå, usikre mellomledd og mulig motbevis. Grensen mot ${bounds} forhindrer at nabofaglige påstander smugles inn uten egne kilder.`
];

